<?php
session_start();
if (empty($_SESSION['user_id'])) { header('Location: /pages/login.php'); exit; }
require_once __DIR__ . '/../config/config.php';
$userId=(int)$_SESSION['user_id'];
$orderId=filter_input(INPUT_GET,'order_id',FILTER_VALIDATE_INT)?:filter_input(INPUT_POST,'order_id',FILTER_VALIDATE_INT);
if(!$orderId){http_response_code(404);exit('ไม่พบคำสั่งซื้อ');}
if(empty($_SESSION['order_review_csrf']))$_SESSION['order_review_csrf']=bin2hex(random_bytes(24));
$orderStmt=$pdo->prepare("SELECT order_id,order_number,shipping_status,created_at FROM orders WHERE order_id=? AND user_id=?");$orderStmt->execute([$orderId,$userId]);$order=$orderStmt->fetch(PDO::FETCH_ASSOC);
if(!$order||$order['shipping_status']!=='delivered'){http_response_code(403);exit('รีวิวได้เฉพาะคำสั่งซื้อที่รับสินค้าสำเร็จแล้ว');}
$error='';$savedItem=0;
if($_SERVER['REQUEST_METHOD']==='POST'){
 $orderItemId=(int)($_POST['order_item_id']??0);$rating=(int)($_POST['rating']??0);$text=trim((string)($_POST['review_text']??''));
 if(!hash_equals($_SESSION['order_review_csrf'],(string)($_POST['csrf_token']??'')))$error='ไม่สามารถยืนยันคำขอได้ กรุณาลองใหม่';
 elseif(isset($_POST['delete_review'])){
  $allowed=$pdo->prepare('SELECT 1 FROM order_items oi JOIN orders o ON o.order_id=oi.order_id WHERE oi.order_item_id=? AND o.order_id=? AND o.user_id=? AND o.shipping_status="delivered"');$allowed->execute([$orderItemId,$orderId,$userId]);
  if(!$allowed->fetchColumn())$error='ไม่พบรีวิวที่สามารถลบได้';
  else{$pdo->prepare('DELETE FROM book_reviews WHERE order_item_id=? AND user_id=?')->execute([$orderItemId,$userId]);header('Location:/pages/review_order.php?order_id='.$orderId.'&deleted='.$orderItemId.'#item-'.$orderItemId);exit;}
 }
 elseif($rating<1||$rating>5)$error='กรุณาเลือกคะแนน 1–5 ดาว';
 elseif(mb_strlen($text)>2000)$error='ข้อความรีวิวยาวเกิน 2,000 ตัวอักษร';
 else{
  $allowed=$pdo->prepare('SELECT oi.book_id FROM order_items oi JOIN orders o ON o.order_id=oi.order_id WHERE oi.order_item_id=? AND o.order_id=? AND o.user_id=? AND o.shipping_status="delivered"');$allowed->execute([$orderItemId,$orderId,$userId]);$bookId=(int)$allowed->fetchColumn();
  if(!$bookId)$error='ไม่พบสินค้าที่สามารถรีวิวได้';
  else{$existing=$pdo->prepare('SELECT review_id FROM book_reviews WHERE order_item_id=?');$existing->execute([$orderItemId]);$existingReviewId=(int)$existing->fetchColumn();$save=$pdo->prepare("INSERT INTO book_reviews(book_id,user_id,order_item_id,rating,review_text) VALUES(?,?,?,?,?) ON DUPLICATE KEY UPDATE rating=VALUES(rating),review_text=VALUES(review_text),updated_at=NOW()");$save->execute([$bookId,$userId,$orderItemId,$rating,$text!==''?$text:null]);if(!$existingReviewId){$reviewId=(int)$pdo->lastInsertId();if(!$reviewId){$existing->execute([$orderItemId]);$reviewId=(int)$existing->fetchColumn();}wanawanNotifyNewReview($pdo,$reviewId,$bookId,$userId);}header('Location:/pages/review_order.php?order_id='.$orderId.'&saved='.$orderItemId.'#item-'.$orderItemId);exit;}
 }
}
$itemsStmt=$pdo->prepare("SELECT oi.order_item_id,oi.book_id,oi.quantity,b.title,b.author,b.image_cover,r.review_id,r.rating,r.review_text FROM order_items oi JOIN books b ON b.book_id=oi.book_id LEFT JOIN book_reviews r ON r.order_item_id=oi.order_item_id AND r.user_id=? WHERE oi.order_id=? ORDER BY oi.order_item_id");$itemsStmt->execute([$userId,$orderId]);$items=$itemsStmt->fetchAll(PDO::FETCH_ASSOC);
$reviewed=count(array_filter($items,fn($i)=>!empty($i['review_id'])));$savedItem=(int)($_GET['saved']??0);$deletedItem=(int)($_GET['deleted']??0);
function roCover(?string $v):?string{if(!$v)return null;if(preg_match('#^https?://#i',$v))return$v;$v=ltrim(str_replace('\\','/',$v),'/');return str_starts_with($v,'uploads/')?'/pages/'.$v:'/assets/image/books/'.$v;}
?>
<!DOCTYPE html><html lang="th"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>รีวิวสินค้าในคำสั่งซื้อ - วนวรรณ</title><link rel="stylesheet" href="../assets/css/styles.css"><style>
*{box-sizing:border-box}.page{max-width:920px;margin:auto;padding:42px 22px 90px}.back{color:var(--secondary-color);text-decoration:none}.head{margin:20px 0 25px}.head h1{margin:0;color:var(--secondary-color);font-size:32px}.head p{color:var(--text-muted)}.progress{height:9px;border-radius:9px;background:#f1e4df;overflow:hidden}.progress span{display:block;height:100%;background:linear-gradient(90deg,#d87d9f,#d49b8d)}.item-card{scroll-margin-top:20px;margin-bottom:22px;padding:26px;border:1px solid #eadbd4;border-radius:20px;background:#fff;box-shadow:0 8px 25px rgba(80,45,35,.06)}.product{display:grid;grid-template-columns:90px 1fr auto;gap:18px;align-items:center;padding-bottom:20px;border-bottom:1px solid #eee1dc}.cover{width:88px;height:116px;border-radius:10px;object-fit:cover;background:#f5e1da}.product h2{font-size:19px;margin:0 0 5px}.status{padding:7px 12px;border-radius:999px;background:#fff0f5;color:#b45378;font-size:12px;font-weight:700}.status.done{background:#edf7e9;color:#537c49}.stars{display:flex;flex-direction:row-reverse;justify-content:flex-end;gap:5px;margin:20px 0 14px}.stars input{position:absolute;opacity:0}.stars label{font-size:37px;color:#ddd;cursor:pointer;transition:.15s}.stars label:hover,.stars label:hover~label,.stars input:checked~label{color:#e0a127;transform:scale(1.05)}textarea{width:100%;min-height:105px;padding:13px;border:1px solid #d9ccc7;border-radius:11px;font:inherit;resize:vertical}.save{margin-top:13px;min-height:46px;padding:0 22px;border:0;border-radius:9px;background:var(--secondary-color);color:#fff;font:inherit;font-weight:700;cursor:pointer}.notice{padding:12px 15px;border-radius:10px;margin:12px 0}.ok{background:#eaf5e6;color:#47733e}.bad{background:#fde8e5;color:#a33}@media(max-width:600px){.product{grid-template-columns:70px 1fr}.cover{width:68px;height:92px}.status{grid-column:2;width:max-content}.item-card{padding:18px}.head h1{font-size:26px}}
</style><style>.review-actions{display:flex;gap:10px;align-items:center;margin-top:13px}.review-actions .save{margin-top:0}.delete-review{min-height:46px;padding:0 20px;border:1px solid #edc5c5;border-radius:9px;background:#fff;color:#b45d5d;font:inherit;font-weight:600;cursor:pointer}.delete-review:hover{background:#fff7f7;border-color:#dc9f9f}@media(max-width:520px){.review-actions{align-items:stretch;flex-direction:column}.review-actions button{width:100%}}</style></head><body><?php require __DIR__.'/../components/header.php';?><main class="page"><a class="back" href="/pages/orders.php?tab=completed">‹ กลับไปรายการสั่งซื้อ</a><header class="head"><h1>รีวิวสินค้าในคำสั่งซื้อ</h1><p>#<?=htmlspecialchars($order['order_number'])?> · รีวิวแล้ว <?=$reviewed?> จาก <?=count($items)?> เล่ม</p><div class="progress"><span style="width:<?=count($items)?($reviewed/count($items)*100):0?>%"></span></div></header><?php if($error):?><div class="notice bad"><?=htmlspecialchars($error)?></div><?php endif;?><?php foreach($items as $index=>$item):?><article class="item-card" id="item-<?=(int)$item['order_item_id']?>"><div class="product"><?php if($cover=roCover($item['image_cover'])):?><img class="cover" src="<?=htmlspecialchars($cover)?>" alt=""><?php endif;?><div><small>เล่มที่ <?=$index+1?></small><h2><?=htmlspecialchars($item['title'])?></h2><span style="color:var(--text-muted)"><?=htmlspecialchars($item['author']?:'-')?> · จำนวน <?=$item['quantity']?> เล่ม</span></div><span class="status <?=$item['review_id']?'done':''?>"><?=$item['review_id']?'✓ รีวิวแล้ว':'รอรีวิว'?></span></div><?php if($savedItem===(int)$item['order_item_id']):?><div class="notice ok">บันทึกรีวิวเล่มนี้เรียบร้อยแล้ว</div><?php elseif($deletedItem===(int)$item['order_item_id']):?><div class="notice ok">ลบรีวิวเล่มนี้เรียบร้อยแล้ว</div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($_SESSION['order_review_csrf'])?>"><input type="hidden" name="order_id" value="<?=$orderId?>"><input type="hidden" name="order_item_id" value="<?=(int)$item['order_item_id']?>"><div class="stars" aria-label="ให้คะแนน <?=htmlspecialchars($item['title'])?>"><?php for($star=5;$star>=1;$star--):?><input id="star-<?=(int)$item['order_item_id']?>-<?=$star?>" type="radio" name="rating" value="<?=$star?>" <?=(int)$item['rating']===$star?'checked':''?> required><label for="star-<?=(int)$item['order_item_id']?>-<?=$star?>" title="<?=$star?> ดาว">★</label><?php endfor;?></div><textarea name="review_text" maxlength="2000" placeholder="รีวิวหนังสือเล่มนี้ คุณภาพสินค้า และการแพ็ก..."><?=htmlspecialchars($item['review_text']??'')?></textarea><div class="review-actions"><button class="save" type="submit"><?=$item['review_id']?'บันทึกการแก้ไข':'ส่งรีวิวเล่มนี้'?></button><?php if($item['review_id']):?><button class="delete-review" type="submit" name="delete_review" value="1" formnovalidate onclick="return confirm('ต้องการลบรีวิวของหนังสือเล่มนี้ใช่หรือไม่?')">ลบรีวิว</button><?php endif;?></div></form></article><?php endforeach;?></main><?php require __DIR__.'/../components/footer.php';?></body></html>
